<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/classes/GreenPortalDatabase.php';
require_once dirname(__DIR__) . '/classes/UsuarioSessao.php';
require_once dirname(__DIR__) . '/classes/PermissaoTransacao.php';
require_once dirname(__DIR__) . '/classes/TransactionSecurity.php';
if (session_status() !== PHP_SESSION_ACTIVE) session_start();
if (empty($_SESSION['autenticado']) || empty($_SESSION['tenant']['banco_dados'])) { http_response_code(401); exit('Sessão expirada.'); }
$env = GreenPortalDatabase::env(); $pdo = TransactionSecurity::connect('REQUISITOS_LEGAIS');
if (!UsuarioSessao::atualizar($pdo, $_SESSION)) { http_response_code(401); exit('Sessão expirada.'); }
$permission = PermissaoTransacao::obter('REQUISITOS_LEGAIS');
register_shutdown_function(static function () use ($permission): void { echo '<script>window.greenResponsibilityPermission=' . json_encode(['edit' => !empty($permission['pode_editar']), 'include' => !empty($permission['pode_incluir']), 'delete' => !empty($permission['pode_excluir'])], JSON_UNESCAPED_SLASHES) . ';</script><script src="../assets/js/responsabilidades-permissoes.js?v=2"></script>'; });
if (($_SERVER['REQUEST_METHOD'] ?? 'GET') !== 'POST' && !$permission['pode_editar'] && !$permission['pode_incluir'] && $permission['pode_excluir']) $permission['pode_incluir'] = true;
if (!$permission['pode_visualizar']) { http_response_code(403); exit('Sem permissão para consultar responsabilidades.'); }
$id = filter_input(INPUT_GET, 'CODSITUACAO', FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]); if (!$id) { http_response_code(400); exit('Situação inválida.'); }
$call = static fn(PDO $db, string $sql, array $params = []): array => GreenPortalDatabase::call($db, $sql, $params); $json = static fn(mixed $value): string => json_encode($value, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES); $e = static fn(mixed $value): string => htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8');
$types = $call($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,100,0)', ['tabela' => 'vw_responsabilidade_tipos', 'filtros' => $json(['MODULO_CODIGO' => 'REQUISITOS_LEGAIS', 'ATIVO' => 1])]);
$users = $call($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,10000,0)', ['tabela' => 'vw_responsabilidade_usuarios_ativos', 'filtros' => $json([])]); $groups = $call($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,10000,0)', ['tabela' => 'vw_responsabilidade_grupos_ativos', 'filtros' => $json([])]); $moduleId = (int)($types[0]['CODMODULO'] ?? 0); $message = ''; $error = '';
$friendlyError = static function (Throwable $exception): string { $raw = $exception->getMessage(); if (str_contains($raw, 'A data final nao pode ser anterior')) return 'A data final não pode ser anterior à data inicial.'; if (str_contains($raw, 'Ja existe vinculo ativo')) return 'Já existe um responsável com este vínculo em um período sobreposto.'; if (str_contains($raw, 'Grupo inexistente') || str_contains($raw, 'Usuario inexistente')) return 'O usuário ou grupo selecionado não está ativo.'; return 'Não foi possível salvar as responsabilidades. Verifique os dados informados.'; };
if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['action'] ?? '') === 'save_rows') {
    if (!$permission['pode_editar'] && !$permission['pode_incluir'] && !$permission['pode_excluir']) { http_response_code(403); exit('Sem permissão para alterar responsabilidades.'); }
    try {
        $existing = $call($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,1000,0)', ['tabela' => 'vw_responsabilidade_requisitos', 'filtros' => $json(['CODSITUACAO' => $id, 'ATIVO' => 1])]); $allowedIds = array_map('intval', array_column($existing, 'CODATRIBUICAO')); $postedKeys = array_map('strval', array_keys((array)($_POST['rows'] ?? [])));
        if ($permission['pode_excluir']) foreach ($existing as $old) {
            if (!in_array((string)$old['CODATRIBUICAO'], $postedKeys, true)) {
                $deleteKey = $json(['CODATRIBUICAO' => (int)$old['CODATRIBUICAO']]);
                $deleteData = $json(['ATIVO' => 0, 'CODUSUARIOALTERACAO' => (int)$_SESSION['usuario']['codusuario']]);
                $call($pdo, 'CALL sp_crud_update(:tabela,:chave,:dados)', ['tabela' => 'responsabilidade_atribuicoes', 'chave' => $deleteKey, 'dados' => $deleteData]);
            }
        }
        $validTypes = array_map('intval', array_column($types, 'CODTIPORESPONSABILIDADE'));
        foreach ((array)($_POST['rows'] ?? []) as $key => $row) {
            $assignmentId = ctype_digit((string)$key) ? (int)$key : 0; if ($assignmentId && !in_array($assignmentId, $allowedIds, true)) throw new RuntimeException('Atribuição inválida para esta situação.');
            if (!empty($row['_delete'])) {
                if ($assignmentId && $permission['pode_excluir']) {
                    $deleteKey = $json(['CODATRIBUICAO' => $assignmentId]);
                    $deleteData = $json(['ATIVO' => 0, 'CODUSUARIOALTERACAO' => (int)$_SESSION['usuario']['codusuario']]);
                    $call($pdo, 'CALL sp_crud_update(:tabela,:chave,:dados)', ['tabela' => 'responsabilidade_atribuicoes', 'chave' => $deleteKey, 'dados' => $deleteData]);
                }
                continue;
            }
            if (!$permission['pode_editar'] && empty($row['CODTIPORESPONSABILIDADE'])) continue;
            $typeId = (int)($row['CODTIPORESPONSABILIDADE'] ?? 0); $destination = strtoupper(trim((string)($row['TIPO_DESTINO'] ?? ''))); $userId = $destination === 'USUARIO' ? max(0, (int)($row['CODUSUARIO'] ?? 0)) : null; $groupId = $destination === 'GRUPO' ? max(0, (int)($row['CODGRUPO'] ?? 0)) : null; $from = trim((string)($row['VALIDO_DE'] ?? '')) ?: date('Y-m-d'); $to = trim((string)($row['VALIDO_ATE'] ?? '')) ?: null;
            if (!in_array($typeId, $validTypes, true) || !in_array($destination, ['USUARIO', 'GRUPO'], true) || ($destination === 'USUARIO' && !$userId) || ($destination === 'GRUPO' && !$groupId)) throw new RuntimeException('Preencha finalidade e responsável em todas as linhas.');
            $call($pdo, 'CALL sp_responsabilidade_validar_duplicidade(:atribuicao,:modulo,:origem,:tipo,:categoria,:entidade,:registro,:destino,:usuario,:grupo,:de,:ate)', ['atribuicao' => $assignmentId ?: null, 'modulo' => $moduleId, 'origem' => 'DIRETA', 'tipo' => $typeId, 'categoria' => null, 'entidade' => 'legislacaoxsituacao', 'registro' => (string)$id, 'destino' => $destination, 'usuario' => $userId, 'grupo' => $groupId, 'de' => $from, 'ate' => $to]);
            $data = ['CODMODULO' => $moduleId, 'ORIGEM' => 'DIRETA', 'CODTIPORESPONSABILIDADE' => $typeId, 'CODCATEGORIARESPONSABILIDADE' => null, 'ENTIDADE' => 'legislacaoxsituacao', 'REGISTRO_ID' => (string)$id, 'TIPO_DESTINO' => $destination, 'CODUSUARIO' => $userId, 'CODGRUPO' => $groupId, 'PRIORIDADE' => (int)($row['PRIORIDADE'] ?? 0), 'PRINCIPAL' => !empty($row['PRINCIPAL']) ? 1 : 0, 'VALIDO_DE' => $from, 'VALIDO_ATE' => $to, 'ATIVO' => 1, 'OBSERVACAO' => trim((string)($row['OBSERVACAO'] ?? '')), 'CODUSUARIOALTERACAO' => (int)$_SESSION['usuario']['codusuario']];
            if ($assignmentId) { if (!$permission['pode_editar']) continue; $call($pdo, 'CALL sp_crud_update(:tabela,:chave,:dados)', ['tabela' => 'responsabilidade_atribuicoes', 'chave' => $json(['CODATRIBUICAO' => $assignmentId]), 'dados' => $json($data)]); } else { if (!$permission['pode_incluir']) continue; $call($pdo, 'CALL sp_crud_insert(:tabela,:dados)', ['tabela' => 'responsabilidade_atribuicoes', 'dados' => $json($data)]); }
        }
        $message = (!$permission['pode_editar'] && !$permission['pode_incluir'] && $permission['pode_excluir'])
            ? 'Operação concluída. Exclusões autorizadas foram processadas; alterações não autorizadas foram ignoradas.'
            : 'Responsabilidades salvas com sucesso.';
    } catch (Throwable $exception) { $error = $friendlyError($exception); }
}
$rows = $call($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,1000,0)', ['tabela' => 'vw_responsabilidade_requisitos', 'filtros' => $json(['CODSITUACAO' => $id, 'ATIVO' => 1])]); $context = $rows[0] ?? []; $situationRows = $call($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,1,0)', ['tabela' => 'legislacaoxsituacao', 'filtros' => $json(['CODSITUACAO' => $id])]); if ($situationRows) $context['DESCRICAO_SITUACAO'] = $situationRows[0]['dscsituacao'] ?? '';
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Manter responsabilidades</title><link rel="stylesheet" href="../assets/vendor/bootstrap/css/bootstrap.min.css?v=2"><link rel="stylesheet" href="../assets/vendor/bootstrap-icons/bootstrap-icons.css?v=2"><link rel="stylesheet" href="../assets/css/app.css?v=1"><?php require_once dirname(__DIR__) . '/components/pagina_padrao.php'; greenPortalEstiloPagina(); ?></head><body class="p-3 bg-light"><main class="container-fluid"><div class="d-flex justify-content-between align-items-start gap-3 mb-3"><div><h4 class="mb-1"><i class="bi bi-pencil-square me-2"></i>Manter responsabilidades</h4><div class="text-muted small">Situação <?= $e($id) ?> — <?= $e($context['DESCRICAO_SITUACAO'] ?? 'Sem descrição') ?></div></div><a class="btn btn-sm btn-outline-secondary" data-testid="toggle-consulta" href="requisito_responsabilidades.php?CODSITUACAO=<?= $e($id) ?>"><i class="bi bi-eye me-1"></i>Consulta</a></div><?php if ($message): ?><div class="alert alert-success py-2"><?= $e($message) ?></div><?php endif; ?><?php if ($error): ?><div class="alert alert-danger py-2"><?= $e($error) ?></div><?php endif; ?><?php if (!$permission['pode_editar'] && !$permission['pode_incluir']): ?><div class="alert alert-warning">Seu perfil não possui permissão para alterar responsabilidades.</div><?php else: ?><form method="post"><input type="hidden" name="action" value="save_rows"><div class="table-responsive border rounded bg-white"><table class="table table-sm align-middle mb-0" id="requisitoResponsibilityTable"><thead class="table-light"><tr><th>Finalidade</th><th>Destino</th><th>Responsável</th><th>Prioridade</th><th>Principal</th><th>Vigência</th><th></th></tr></thead><tbody><?php foreach ($rows as $row): $key=(int)$row['CODATRIBUICAO']; ?><tr data-row-key="<?= $key ?>"><td><select class="form-select form-select-sm" name="rows[<?= $key ?>][CODTIPORESPONSABILIDADE]"><?php foreach ($types as $type): ?><option value="<?= $e($type['CODTIPORESPONSABILIDADE']) ?>"<?= (string)$type['CODIGO'] === (string)$row['TIPO_CODIGO'] ? ' selected' : '' ?>><?= $e($type['NOME']) ?></option><?php endforeach; ?></select></td><td><select class="form-select form-select-sm js-destination" name="rows[<?= $key ?>][TIPO_DESTINO]"><option value="USUARIO"<?= $row['TIPO_DESTINO'] === 'USUARIO' ? ' selected' : '' ?>>Usuário</option><option value="GRUPO"<?= $row['TIPO_DESTINO'] === 'GRUPO' ? ' selected' : '' ?>>Grupo</option></select></td><td><select class="form-select form-select-sm js-user" name="rows[<?= $key ?>][CODUSUARIO]"><option value="">Selecione</option><?php foreach ($users as $user): ?><option value="<?= $e($user['CODUSUARIO']) ?>"<?= (int)$user['CODUSUARIO'] === (int)$row['CODUSUARIO'] ? ' selected' : '' ?>><?= $e($user['NOME']) ?></option><?php endforeach; ?></select><select class="form-select form-select-sm js-group d-none" name="rows[<?= $key ?>][CODGRUPO]"><option value="">Selecione</option><?php foreach ($groups as $group): ?><option value="<?= $e($group['CODGRUPO']) ?>"<?= (int)$group['CODGRUPO'] === (int)$row['CODGRUPO'] ? ' selected' : '' ?>><?= $e($group['NOME']) ?></option><?php endforeach; ?></select></td><td><input class="form-control form-control-sm" type="number" min="0" name="rows[<?= $key ?>][PRIORIDADE]" value="<?= $e($row['PRIORIDADE']) ?>"></td><td class="text-center"><input type="checkbox" name="rows[<?= $key ?>][PRINCIPAL]" value="1"<?= !empty($row['PRINCIPAL']) ? ' checked' : '' ?>></td><td><div class="d-flex gap-1"><input class="form-control form-control-sm" type="date" name="rows[<?= $key ?>][VALIDO_DE]" value="<?= $e($row['VALIDO_DE']) ?>"><input class="form-control form-control-sm" type="date" name="rows[<?= $key ?>][VALIDO_ATE]" value="<?= $e($row['VALIDO_ATE']) ?>"></div></td><td><button type="button" class="btn btn-sm btn-outline-danger js-delete-row" title="Remover" data-testid="delete-responsibility-row"><i class="bi bi-trash"></i></button></td></tr><?php endforeach; ?></tbody></table></div><div class="d-flex justify-content-between mt-3"><button type="button" class="btn btn-sm btn-outline-primary" id="addRequisitoResponsibility" data-testid="add-responsibility-row"><i class="bi bi-plus-lg me-1"></i>Adicionar</button><button type="submit" class="btn btn-sm btn-success" id="saveRequisitoResponsibilities" data-testid="save-responsibilities"><i class="bi bi-check2 me-1"></i>Salvar</button></div></form><?php endif; ?></main><script>document.addEventListener('DOMContentLoaded',function(){var table=document.querySelector('#requisitoResponsibilityTable tbody'),types=<?= json_encode($types, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>,users=<?= json_encode($users, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>,groups=<?= json_encode($groups, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>,seq=0;function options(items,id){return '<option value="">Selecione</option>'+items.map(function(x){return '<option value="'+x[id]+'">'+String(x.NOME||'').replace(/</g,'&lt;')+'</option>';}).join('');}function toggle(row){var group=row.querySelector('.js-destination').value==='GRUPO';row.querySelector('.js-user').classList.toggle('d-none',group);row.querySelector('.js-group').classList.toggle('d-none',!group);}function bind(row){toggle(row);row.querySelector('.js-destination').addEventListener('change',function(){toggle(row);});}document.querySelectorAll('#requisitoResponsibilityTable tr[data-row-key]').forEach(bind);document.querySelector('#addRequisitoResponsibility')?.addEventListener('click',function(){var key='novo_'+(++seq),row=document.createElement('tr');row.innerHTML='<td><select class="form-select form-select-sm" name="rows['+key+'][CODTIPORESPONSABILIDADE]">'+types.map(function(x){return '<option value="'+x.CODTIPORESPONSABILIDADE+'">'+x.NOME+'</option>';}).join('')+'</select></td><td><select class="form-select form-select-sm js-destination" name="rows['+key+'][TIPO_DESTINO]"><option value="USUARIO">Usuário</option><option value="GRUPO">Grupo</option></select></td><td><select class="form-select form-select-sm js-user" name="rows['+key+'][CODUSUARIO]">'+options(users,'CODUSUARIO')+'</select><select class="form-select form-select-sm js-group d-none" name="rows['+key+'][CODGRUPO]">'+options(groups,'CODGRUPO')+'</select></td><td><input class="form-control form-control-sm" type="number" min="0" name="rows['+key+'][PRIORIDADE]" value="0"></td><td class="text-center"><input type="checkbox" name="rows['+key+'][PRINCIPAL]" value="1"></td><td><div class="d-flex gap-1"><input class="form-control form-control-sm" type="date" name="rows['+key+'][VALIDO_DE]" value="<?= date('Y-m-d') ?>"><input class="form-control form-control-sm" type="date" name="rows['+key+'][VALIDO_ATE]" value=""></div></td><td><button type="button" class="btn btn-sm btn-outline-danger js-delete-row" data-testid="delete-responsibility-row"><i class="bi bi-trash"></i></button></td>';table.appendChild(row);bind(row);});document.addEventListener('click',function(event){var button=event.target.closest('.js-delete-row');if(!button)return;var row=button.closest('tr'),key=row.getAttribute('data-row-key');if(key){var hidden=document.createElement('input');hidden.type='hidden';hidden.name='rows['+key+'][_delete]';hidden.value='1';row.appendChild(hidden);}row.remove();});});</script></body></html>
